  Int n_slave;
  Int n_slave_field;
  Int ix1_slave;
  Int slave_status;
  Int n_lord;
  Int n_lord_field;
  Int n_lord_ramper;
  Int ic1_lord;
  Int ix_pointer;
  Int ixx;
  Int iyy;
  Int izz;
  Int mat6_calc_method;
  Int tracking_method;
  Int spin_tracking_method;
  Int csr_method;
  Int space_charge_method;
  Int ptc_integration_type;
  Int field_calc;
  Int aperture_at;
  Int aperture_type;
  Int ref_species;
  Int orientation;
  Bool symplectify;
  Bool mode_flip;
  Bool multipoles_on;
  Bool scale_multipoles;
  Bool taylor_map_includes_offsets;
  Bool field_master;
  Bool is_on;
  Bool logic;
  Bool bmad_logic;
  Bool select;
  Bool offset_moves_aperture;

  void class_init (const int key_) {
    key = key_;

    if (key == Bmad::LCAVITY) {
      value[Bmad::COUPLER_AT] = Bmad::DOWNSTREAM_END;
      value[Bmad::FIELD_AUTOSCALE] = 1;
      value[Bmad::N_CELL] = 1;
    }

    if (key == Bmad::RFCAVITY) {
      value[Bmad::COUPLER_AT] = Bmad::DOWNSTREAM_END;
      value[Bmad::FIELD_AUTOSCALE] = 1;
      value[Bmad::N_CELL] = 1;
    }

    if (key == Bmad::RBEND || key == Bmad::SBEND) {
      value[Bmad::FRINGE_AT] = Bmad::BOTH_ENDS;
      value[Bmad::FRINGE_TYPE] = Bmad::BASIC_BEND;
      value[Bmad::PTC_FIELD_GEOMETRY] = Bmad::SECTOR;
    }
  }

  CPP_ele(const int key_ = 0) :
    name(),
    type(),
    alias(),
    component_name(),
    descrip(NULL),
    a(),
    b(),
    z(),
    x(),
    y(),
    ac_kick(NULL),
    bookkeeping_state(),
    control(NULL),
    floor(),
    high_energy_space_charge(NULL),
    mode3(NULL),
    photon(NULL),
    rad_map(NULL),
    taylor(CPP_taylor_ARRAY(6)),
    spin_taylor_ref_orb_in(6, Bmad::REAL_GARBAGE),
    spin_taylor(CPP_taylor_ARRAY(4)),
    wake(NULL),
    wall3d(CPP_wall3d_ARRAY(0)),
    cartesian_map(CPP_cartesian_map_ARRAY(0)),
    cylindrical_map(CPP_cylindrical_map_ARRAY(0)),
    gen_grad_map(CPP_gen_grad_map_ARRAY(0)),
    grid_field(CPP_grid_field_ARRAY(0)),
    map_ref_orb_in(),
    map_ref_orb_out(),
    time_ref_orb_in(),
    time_ref_orb_out(),
    value(Bmad::NUM_ELE_ATTRIB+1, double(0)),
    old_value(Bmad::NUM_ELE_ATTRIB+1, double(0)),
    spin_q(Real_MATRIX(4, Real_ARRAY(7))),
    vec0(6, 0.0),
    mat6(Real_MATRIX(6, Real_ARRAY(6))),
    c_mat(Real_MATRIX(2, Real_ARRAY(2))),
    gamma_c(1),
    s_start(0.0),
    s(0.0),
    ref_time(0.0),
    a_pole(0, 0.0),
    b_pole(0, 0.0),
    a_pole_elec(0, 0.0),
    b_pole_elec(0, 0.0),
    custom(0, 0.0),
    r(Real_TENSOR(0, Real_MATRIX(0, Real_ARRAY(0)))),
    key(key_),
    sub_key(0),
    ix_ele(-1),
    ix_branch(0),
    lord_status(Bmad::NOT_A_LORD),
    n_slave(0),
    n_slave_field(0),
    ix1_slave(0),
    slave_status(Bmad::FREE),
    n_lord(0),
    n_lord_field(0),
    n_lord_ramper(0),
    ic1_lord(0),
    ix_pointer(0),
    ixx(0),
    iyy(0),
    izz(0),
    mat6_calc_method(Bmad::BMAD_STANDARD),
    tracking_method(Bmad::BMAD_STANDARD),
    spin_tracking_method(Bmad::BMAD_STANDARD),
    csr_method(Bmad::OFF),
    space_charge_method(Bmad::OFF),
    ptc_integration_type(Bmad::MATRIX_KICK),
    field_calc(Bmad::BMAD_STANDARD),
    aperture_at(Bmad::DOWNSTREAM_END),
    aperture_type(Bmad::RECTANGULAR),
    ref_species(Bmad::NOT_SET),
    orientation(1),
    symplectify(false),
    mode_flip(false),
    multipoles_on(true),
    scale_multipoles(true),
    taylor_map_includes_offsets(true),
    field_master(false),
    is_on(true),
    logic(false),
    bmad_logic(false),
    select(false),
    offset_moves_aperture(false)
    {std::cout << "CPP_ele(): " << this << std::endl;
    {
      class_init(key);
    }
}

